var i=`0451-adana-kebab`;var a=`world-0451`;var t=`TR`;var r=`western-asia`;var l=4;var s=37;var o={en:`Adana Kebab`,ua:`Адана-кебаб`};var d={en:`A traditional dish from Türkiye, centered on ground lamb, red bell pepper, yellow onion, parsley. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: фарш з ягнятини, червоний солодкий перець, жовта цибуля, петрушка. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Finely chop red pepper into the lamb mince and work with the spices until tacky; keep the mix chilled.`,ua:`Дрібно наріжте перець і вимісіть його з баранячим фаршем та спеціями до липкості; тримайте фарш охолодженим.`,t:[`mixing`],m:8,i:[[`ground-lamb`,700,`g`],[`red-bell-pepper`,110,`g`],[`hot-paprika`,7,`g`],[`ground-cumin`,5,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:12,i:[]},{en:`Grill over medium-high heat for about 14 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 14 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:14,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`yellow-onion`,130,`g`],[`sumac`,6,`g`],[`parsley`,25,`g`]]}];var u={slug:i,id:a,country:`TR`,region:r,servings:4,minutes:37,title:o,text:d,steps:g};export{t as country,u as default,a as id,s as minutes,r as region,l as servings,i as slug,g as steps,d as text,o as title};